"""Strict CSV parsing, formatting, and JSON conversion utility."""

from __future__ import annotations

import csv
import io
import json
import sys
from collections.abc import Iterable, Mapping
from typing import Any

_HEADER = ["name", "note"]


def _parse_rows(text: str) -> list[list[str]]:
    """Parse CSV while rejecting quotes outside their permitted positions."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    rows: list[list[str]] = []
    row: list[str] = []
    field: list[str] = []
    state = "start"
    index = 0
    length = len(text)

    def finish_field() -> None:
        row.append("".join(field))
        field.clear()

    def finish_row() -> None:
        finish_field()
        rows.append(row.copy())
        row.clear()

    while index < length:
        char = text[index]

        if state == "quoted":
            if char == '"':
                state = "after_quote"
            else:
                field.append(char)
            index += 1
            continue

        if state == "after_quote":
            if char == '"':
                field.append('"')
                state = "quoted"
                index += 1
                continue
            if char == ",":
                finish_field()
                state = "start"
                index += 1
                continue
            if char in "\r\n":
                finish_row()
                state = "start"
                if char == "\r" and index + 1 < length and text[index + 1] == "\n":
                    index += 2
                else:
                    index += 1
                continue
            raise ValueError(f"malformed CSV quoting at character {index + 1}")

        if char == ",":
            finish_field()
            state = "start"
            index += 1
            continue

        if char in "\r\n":
            finish_row()
            state = "start"
            if char == "\r" and index + 1 < length and text[index + 1] == "\n":
                index += 2
            else:
                index += 1
            continue

        if char == '"':
            if state != "start":
                raise ValueError(f"malformed CSV quoting at character {index + 1}")
            state = "quoted"
            index += 1
            continue

        field.append(char)
        state = "unquoted"
        index += 1

    if state == "quoted":
        raise ValueError("malformed CSV quoting: unterminated quoted field")

    # A terminator finishes its record; otherwise the pending record still needs
    # to be committed. Empty input is committed so it reports a missing header.
    ended_with_record_separator = length > 0 and text[-1] in "\r\n" and state == "start" and not row and not field
    if not ended_with_record_separator:
        finish_row()

    return rows


def parse_records(text: str) -> list[dict[str, str]]:
    """Parse CSV with the exact header ``name,note`` into record dictionaries."""
    rows = _parse_rows(text)
    if not rows or rows[0] != _HEADER:
        raise ValueError("CSV header must be exactly: name,note")

    records: list[dict[str, str]] = []
    for line_number, row in enumerate(rows[1:], start=2):
        if len(row) != 2:
            raise ValueError(
                f"CSV row {line_number} has {len(row)} columns; expected 2"
            )
        records.append({"name": row[0], "note": row[1]})
    return records


def format_records(records: Iterable[Mapping[str, Any]]) -> str:
    """Serialize records as CSV with a fixed header and LF line endings."""
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    try:
        iterator = iter(records)
    except TypeError as exc:
        raise ValueError("records must be an iterable of mappings") from exc

    for record_number, record in enumerate(iterator, start=1):
        if not isinstance(record, Mapping):
            raise ValueError(f"record {record_number} must be a mapping")
        if set(record.keys()) != set(_HEADER):
            raise ValueError(
                f"record {record_number} must contain exactly the keys name and note"
            )
        name = record["name"]
        note = record["note"]
        if not isinstance(name, str) or not isinstance(note, str):
            raise ValueError(f"record {record_number} values must be strings")
        writer.writerow([name, note])

    return output.getvalue()


def to_json(text: str) -> str:
    """Convert valid input CSV to JSON without changing field strings."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main() -> int:
    text = sys.stdin.read()
    try:
        result = to_json(text)
    except ValueError as exc:
        sys.stderr.write(f"invalid CSV: {exc}\n")
        return 2
    sys.stdout.write(result + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
